package com.backend.nutri_predic.plandia.dto; import com.backend.nutri_predic.plandia.entity.PlanDiario; import java.math.BigDecimal; import java.time.LocalDate; public record PlanDiarioResponse(Long id,Long prediccionModeloOrigenId,LocalDate fechaObjetivo,String estado,BigDecimal energiaMinKcal,BigDecimal energiaMaxKcal,BigDecimal proteinaMinG,BigDecimal proteinaMaxG,BigDecimal carbohidratosMinG,BigDecimal carbohidratosMaxG,BigDecimal grasasMinG,BigDecimal grasasMaxG,BigDecimal aguaMinMl,BigDecimal aguaMaxMl,String fuenteReferencia,String versionReferencia,String motivoNoDisponible){public static PlanDiarioResponse from(PlanDiario x){return new PlanDiarioResponse(x.getId(),x.getPrediccionModeloOrigen()==null?null:x.getPrediccionModeloOrigen().getId(),x.getFechaObjetivo(),x.getEstado().name(),x.getEnergiaMinKcal(),x.getEnergiaMaxKcal(),x.getProteinaMinG(),x.getProteinaMaxG(),x.getCarbohidratosMinG(),x.getCarbohidratosMaxG(),x.getGrasasMinG(),x.getGrasasMaxG(),x.getAguaMinMl(),x.getAguaMaxMl(),x.getFuenteReferencia(),x.getVersionReferencia(),x.getMotivoNoDisponible());}}
